const body = $json.body ?? $json;
const cfg = {"workflowKey":"023-churn-risk-alert","department":"Customer Operations","operation":"Churn-Risk Alert","riskLevel":"LOW","defaultApproval":false};
if (!body || typeof body !== 'object' || Array.isArray(body)) throw new Error('A JSON object is required');
const correlationId = String(body.correlationId ?? body.correlation_id ?? $execution.id);
const subjectType = String(body.subjectType ?? body.subject_type ?? 'customer');
const subjectId = String(body.subjectId ?? body.subject_id ?? body.customerId ?? body.caseId ?? correlationId);
