const confidence = Math.max(0, Math.min(1, Number(body.confidence ?? 1)));
const requiresHumanApproval = cfg.defaultApproval || amount >= 1000 || confidence < 0.7 || body.forceHumanReview === true;
const status = requiresHumanApproval ? 'AWAITING_APPROVAL' : 'READY';
return [{json:{correlationId,workflowKey:cfg.workflowKey,department:cfg.department,operation:cfg.operation,subjectType,subjectId,riskLevel:cfg.riskLevel,confidence,requiresHumanApproval,status,input:body,result:{accepted:true,nextStep:requiresHumanApproval?'HUMAN_APPROVAL':'DEPARTMENT_ACTION'},receivedAt:new Date().toISOString()}}];
